const records=k=>(S.records||[]).filter(r=>r.kind===k),get=id=>S.records.find(r=>r.id===id),name=id=>get(id)?.data.name||get(id)?.data.title||'—',finance=()=>['owner','finance','partner'].includes(S.role),write=()=>['owner','finance'].includes(S.role),owner=()=>S.role==='owner',visible=()=>S.role==='sales'?['sales','customers','appointments','settings']:S.role==='staff'?['production','settings']:Object.keys(titles),m=v=>privateMoney?'••••':money(v),badge=s=>`<span class="badge ${['draft','pending','review'].includes(s)?'warn':''}">${esc(names[s]||s||'—')}</span>`;
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${({overview:'<path d="M3 10 12 3l9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',customers:'<circle cx="8" cy="8" r="3"/><circle cx="17" cy="9" r="2"/><path d="M2 21v-3c0-6 12-6 12 0v3m1-7c5-2 7 2 7 5v2"/>',contracts:'<path d="M5 3h14v18H5Z"/><path d="M8 8h8M8 12h8M8 16h5"/>',production:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="m10 9 5 4-5 4Z"/>',finance:'<rect x="2" y="6" width="20" height="14" rx="3"/><path d="M3 6V3h15v3m-2 6h6"/>',payroll:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3c0-7 16-7 16 0v3"/>',sales:'<path d="m3 18 6-6 4 3 8-10m-6 0h6v6"/>',appointments:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',campaigns:'<path d="m4 9 16-5v15L4 14Zm2 5 2 7h4l-2-6"/>',partners:'<path d="m3 9 5-5 4 3 4-3 5 5-3 10H6Z"/><path d="m7 12 5 4 5-4"/>',reports:'<path d="M4 3h16v18H4ZM8 7h8m-8 5h8m-8 5h5"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>'})[k]||''}</svg>`;
const btn=(label,action,extra='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
