const action=(op,label,idkey,id)=>btn(label||opnames[op],'post',`data-op="${op}" ${idkey?`data-${idkey}="${id}"`:''}`,'small');
const toolbar=(addLabel,kind)=>`<div class="toolbar"><input id="search" type="search" value="${esc(search)}" placeholder="بحث بالاسم أو الوصف" aria-label="بحث">${addLabel&&(write()||(S.role==='sales'&&kind==='customer'))?btn('+ '+addLabel,'record',`data-kind="${kind}"`,'primary'):''}</div>`;
