if(kind==='contract'){fields+=select('customer_id','العميل',opts('customer'),d.customer_id)+select('type','نوع العقد',[['package','باقة محددة الفترة'],['units','خدمات بالوحدة'],['project','مشروع / خدمة واحدة'],['retainer','إدارة مستمرة عبر الفترة']],d.type||'package')+input('start_date','بداية الفترة',d.start_date||today(),'date',true)+input('end_date','نهاية الفترة',d.end_date||endOfCycle(today()),'date',true)+status+select('sales_employee_id','مسؤول البيع للعمولة',[['','بدون عمولة'],...opts('employee')],d.sales_employee_id||'')+input('commission_pct','نسبة عمولة الخدمات المحصلة',d.commission_pct||0,'number');fields+=`<div class="full"><h3>بنود العقد والتخصيص بعد الخصم</h3><small>أدخل قيمة بيع الوحدة ضمن سعر العقد؛ الإجمالي يُحسب من البنود.</small>${['video','design','content','service'].map(s=>{const i=d.items?.find(x=>x.service===s)||{};return `<div class="item-inputs"><span>${names[s]}</span><input type="number" name="qty_${s}" value="${i.qty||0}" min="0" step="1" aria-label="عدد ${names[s]}"><input type="number" name="rate_${s}" value="${i.rate||0}" min="0" step="0.01" aria-label="قيمة وحدة ${names[s]}"></div>`;}).join('')}</div>`;hint='التجديد عقد جديد. فوترة العقد تثبت المطالبة والإيراد المؤجل، والتسليم يثبت الإيراد المكتسب.';}
