function bind(){app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handle(b));app.querySelector('#month')?.addEventListener('change',e=>{month=e.target.value;render()});app.querySelector('#account')?.addEventListener('change',e=>{account=e.target.value;render()});app.querySelector('#search')?.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;render();const el=app.querySelector('#search');el?.focus();el?.setSelectionRange(pos,pos)});}
function download(text,name,type){const u=globalThis.URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();globalThis.URL.revokeObjectURL(u);}
function login(){app.innerHTML=`<section class="card login"><img src="../dashboard/riwa-logo.png" alt="رواء"><h1>دفتر رواء الجديد</h1><p class="muted">ادخل بحسابك الحالي. المالية محفوظة بصلاحيات مستقلة.</p><form id="loginform"><label for="email">البريد الإلكتروني<input id="email" type="email" name="email" autocomplete="email" required></label><label for="password">كلمة المرور<input id="password" type="password" name="password" autocomplete="current-password" required></label><div class="error" id="loginerror" role="alert"></div><button class="btn primary" type="submit">تسجيل الدخول</button></form><p style="margin-top:18px"><a href="../dashboard/">فتح النسخة السابقة ↗</a></p></section>`;app.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const v=Object.fromEntries(new FormData(e.target)),r=await sb.auth.signInWithPassword(v);if(r.error)throw r.error;await load(true);}catch(err){app.querySelector('#loginerror').textContent=err.message;}finally{b.disabled=false;}};}
function blocked(msg){app.innerHTML=`<section class="card login"><h1>الوصول للدفتر</h1><p class="error" style="margin:20px 0">${esc(msg)}</p>${btn('إعادة المحاولة','retry','','primary')}<p style="margin-top:18px"><a href="../dashboard/">النسخة السابقة</a></p></section>`;app.querySelector('button').onclick=()=>load(true);}
function startEvents(){if(realtime||!S.role)return;realtime=sb.channel('rwa2-operations').on('postgres_changes',{event:'UPDATE',schema:'public',table:'rwa2_revision',filter:'id=eq.1'},event=>{if(Number(event.new.revision)<=Number(S.revision||0))return;if(busy||modal.open){pendingUpdate=true;return;}load();}).subscribe();}
modal.addEventListener('close',()=>{if(pendingUpdate){pendingUpdate=false;queueMicrotask(()=>load());}});
chan.onmessage=()=>{if(S.role&&!busy&&!modal.open)load()};document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&S.role&&!modal.open&&Date.now()-lastLoad>30000)load()});
try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.116.0');sb=createClient(URL,KEY);const {data,error}=await sb.auth.getSession();if(error)throw error;if(data.session)await load(true);else login();}catch(e){blocked('تعذر الاتصال: '+e.message)}
